    schema: 'stellar-forge.sf81.capability-probe.v1',
    supported: code === 'OPERATOR_BROWSER_REVIEW_SUPPORTED',
    code, selection, capabilities,
  });
  if (signal?.aborted) return result('OPERATOR_CAPABILITIES_ABORTED');
