      child = spawn(python, ['-I', '-B', '-u', helper, '--capabilities'], {
        env: { LANG: 'C.UTF-8', LC_ALL: 'C.UTF-8' },
        shell: false, windowsHide: true, stdio: ['ignore', 'pipe', 'ignore'],
      });
