    publicKeySha256: setup.publicKeySha256, connectionFile: setup.connectionFile,
    discoveryOrigin: operator.origin, policySha256: operator.policySha256,
    ...(ui ? { workspaceOrigin: ui.origin, launchFile } : {}), closed, close };
}

